// Generated by Selenium IDE
const { Builder, By, Key, until } = require('selenium-webdriver')
const assert = require('assert')
describe('Jacket_Crown', function() {
this.timeout(30000)
let driver
let vars
beforeEach(async function() {
driver = await new Builder().forBrowser('firefox').build()
vars = {}
})
afterEach(async function() {
await driver.quit();
})
it('Jacket_Crown', async function() {
// Step 1 | open | http://localhost:3000/login | 
await driver.get("http://localhost:3000/login")
// Step 2 | setWindowSize | 1064x784 | 
await driver.manage().window().setRect({ width: 1064, height: 784 })
// Step 3 | type | id=password | dentabase
const passInput = await driver.wait(until.elementLocated(By.id("password")), 8000)
await driver.wait(until.elementIsVisible(passInput), 8000)
await passInput.sendKeys("dentabase")
// Step 4 | click | id=login-button | 
const loginBtn = await driver.wait(until.elementLocated(By.id("login-button")), 8000)
await driver.wait(until.elementIsVisible(loginBtn), 8000)
await driver.wait(until.elementIsEnabled(loginBtn), 8000)
await loginBtn.click()
// Step 5 | waitForUrl | urlContains=/to-do | 
await driver.wait(until.urlContains("/to-do"), 8000)
// Step 6 | click | css=a[href="/patient_list"] span.sidebar-text | 
const patientMenu = await driver.wait(until.elementLocated(By.css('a[href="/patient_list"] span.sidebar-text')), 8000)
await patientMenu.click()
// Step 7 | click | linkText=John Doe | 
await driver.findElement(By.linkText("John Doe")).click()
// Step 8 | click | linkText=Dental Record Chart | 
await driver.findElement(By.linkText("Dental Record Chart")).click()
// Step 9 | click | css=.dc-code-grid:nth-child(5) > .dc-code-btn:nth-child(3) | 
const codeBtn = await driver.wait(until.elementLocated(By.css(".dc-code-grid:nth-child(5) > .dc-code-btn:nth-child(3)")), 8000)
await driver.executeScript("arguments[0].scrollIntoView({block:'center'});", codeBtn)
await driver.executeScript("arguments[0].click();", codeBtn)
// Step 10 | click | css=#q1 > .tooth-container:nth-child(7) .s-top | 
const toothTop = await driver.wait(until.elementLocated(By.css("#q1 > .tooth-container:nth-child(7) .s-top")), 8000)
await driver.executeScript("arguments[0].scrollIntoView({block:'center'});", toothTop)
await driver.executeScript("arguments[0].click();", toothTop)
// Step 11 | click | css=.dc-tool-btn:nth-child(3) | 
const toolBtn = await driver.wait(until.elementLocated(By.css(".dc-tool-btn:nth-child(3)")), 8000)
await toolBtn.click()
// Step 12 | click | css=.selected .s-top | 
const selectedTop = await driver.wait(until.elementLocated(By.css(".selected .s-top")), 8000)
await driver.executeScript("arguments[0].scrollIntoView({block:'center'});", selectedTop)
await driver.executeScript("arguments[0].click();", selectedTop)
// Step 13 | click | css=.dc-save-btn | 
const saveBtn = await driver.wait(until.elementLocated(By.css(".dc-save-btn")), 8000)
await driver.executeScript("arguments[0].scrollIntoView({block:'center'});", saveBtn)
await driver.executeScript("arguments[0].click();", saveBtn)
// Step 14 | assertAlert | Dental Chart Saved Successfully! | 
await driver.wait(until.alertIsPresent(), 5000)
const alert = await driver.switchTo().alert()
const text = await alert.getText()
assert.strictEqual(text,"Dental Chart Saved Successfully!")
await alert.accept()
})
})